CREATE TABLE material_purchases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by text NOT NULL, purchase_date date NOT NULL DEFAULT current_date, supplier_id uuid NOT NULL REFERENCES suppliers(id), material_id uuid NOT NULL REFERENCES materials(id), quantity numeric(14,3) NOT NULL DEFAULT 0, unit text NOT NULL, unit_price numeric(14,4) NOT NULL DEFAULT 0, subtotal numeric(14,2) NOT NULL DEFAULT 0, gst_rate numeric(5,2) NOT NULL DEFAULT 0, gst_amount numeric(14,2) NOT NULL DEFAULT 0, transport_cost numeric(14,2) NOT NULL DEFAULT 0, total_amount numeric(14,2) NOT NULL DEFAULT 0, invoice_no text, notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(created_by,invoice_no,material_id))